const response = $input.first().json;

// Берём актуальный offset из узла Read Telegram Offset
const savedOffset = Number(
  $('Read Telegram Offset').first().json.offset
);

if (
  !response.ok ||
  !Array.isArray(response.result) ||
  response.result.length === 0
) {
  return [];
}

// Оставляем только сообщения, которые не старше сохранённого offset
const validUpdates = response.result
  .filter(item => Number(item.update_id) >= savedOffset)
  .sort((a, b) => Number(a.update_id) - Number(b.update_id));

if (validUpdates.length === 0) {
  return [];
}

// Берём самое раннее новое сообщение
const update = validUpdates[0];

if (!update.message) {
  return [];
}

const message = update.message;

let contentType = 'unknown';
let content = '';
let voiceFileId = null;
let voiceDuration = null;
let voiceMimeType = null;

if (message.text) {
  contentType = 'text';
  content = message.text;
}

if (message.voice) {
  contentType = 'voice';
  content = '';
  voiceFileId = message.voice.file_id;
  voiceDuration = message.voice.duration;
  voiceMimeType = message.voice.mime_type || 'audio/ogg';
}

return [
  {
    json: {
      update_id: update.update_id,
      next_offset: update.update_id + 1,

      chat_id: message.chat.id,
      user_id: message.from.id,
      username: message.from.username || null,
      first_name: message.from.first_name || null,

      content_type: contentType,
      content,

      voice_file_id: voiceFileId,
      voice_duration: voiceDuration,
      voice_mime_type: voiceMimeType,

      date: message.date
    }
  }
];

const fs = require('fs');

const statePath = '/data/state/telegram-state.json';

let state = { offset: 0 };

if (fs.existsSync(statePath)) {
  state = JSON.parse(fs.readFileSync(statePath, 'utf8'));
}

return [
  {
    json: {
      offset: state.offset || 0
    }
  }
];

const fs = require('fs');

const data = $input.first().json;

const statePath = '/data/state/telegram-state.json';

const state = {
  offset: data.next_offset
};

fs.writeFileSync(statePath, JSON.stringify(state, null, 2), 'utf8');

return [
  {
    json: {
      ...data,
      offset_saved: true,
      saved_offset: data.next_offset
    }
  }
];

