const data = $input.first().json;

const allowedTypes = [
  'note',
  'task',
  'project',
  'calendar_event',
  'idea',
  'purchase',
  'question',
  'journal',
  'reference',
  'unknown'
];

const allowedDestinations = [
  'inbox',
  'projects',
  'knowledge',
  'journal',
  'calendar',
  'tasks',
  'shopping',
  'archive'
];

function normalizeString(value, fallback = '') {
  return String(value || fallback).trim();
}

function normalizeArray(value) {
  if (!Array.isArray(value)) return [];

  return [...new Set(
    value
      .map(item => String(item || '').trim().toLowerCase())
      .filter(Boolean)
  )];
}

function normalizeRecurrence(value) {
  if (
    typeof value !== 'string' ||
    !value.trim().startsWith('RRULE:')
  ) {
    return null;
  }

  let recurrence = value.trim();

  recurrence = recurrence.replace(
    /UNTIL=(\d{8})T(\d{6})(?!Z)/,
    (match, datePart, timePart) => {
      const localUntil = DateTime.fromFormat(
        `${datePart}T${timePart}`,
        "yyyyMMdd'T'HHmmss",
        {
          zone: 'Asia/Novosibirsk'
        }
      );

      if (!localUntil.isValid) {
        return match;
      }

      return `UNTIL=${localUntil
        .toUTC()
        .toFormat("yyyyMMdd'T'HHmmss'Z'")}`;
    }
  );

  return recurrence;
}

const aiType = allowedTypes.includes(data.ai_type)
  ? data.ai_type
  : 'unknown';

const aiDestination = allowedDestinations.includes(data.ai_destination)
  ? data.ai_destination
  : 'inbox';

const aiTitle = normalizeString(data.ai_title, 'Untitled');
const aiSummary = normalizeString(data.ai_summary, aiTitle);

const aiContent = normalizeString(
  data.ai_content || data.content,
  ''
)
  .replace(/^=/, '')
  .trim();

const aiPriority = ['low', 'normal', 'high'].includes(data.ai_priority)
  ? data.ai_priority
  : 'normal';

const aiConfidence = Number(data.ai_confidence);

const normalizedConfidence =
  Number.isFinite(aiConfidence)
    ? Math.min(Math.max(aiConfidence, 0), 1)
    : 0;

const durationValue = Number(data.ai_duration_minutes);

const normalizedDurationMinutes =
  Number.isFinite(durationValue) && durationValue > 0
    ? Math.round(durationValue)
    : null;

const normalizedAllDay =
  data.ai_all_day === true ||
  String(data.ai_all_day).toLowerCase() === 'true';

const normalizedRecurrence =
  normalizeRecurrence(data.ai_recurrence);

return [
  {
    json: {
      ...data,

      ai_type: aiType,
      ai_destination: aiDestination,
      ai_title: aiTitle,
      ai_summary: aiSummary,
      ai_content: aiContent,
      ai_priority: aiPriority,
      ai_tags: normalizeArray(data.ai_tags),
      ai_entities: normalizeArray(data.ai_entities),
      ai_datetime: data.ai_datetime || null,
      ai_confidence: normalizedConfidence,

      ai_duration_minutes: normalizedDurationMinutes,
      ai_all_day: normalizedAllDay,
      ai_recurrence: normalizedRecurrence,

      normalized: true
    }
  }
];

const data = $input.first().json;

const routes = {
  purchase: {
    system: 'obsidian',
    folder: '00 Inbox/Shopping'
  },

  task: {
    system: 'obsidian',
    folder: '00 Inbox/Tasks'
  },

  idea: {
    system: 'obsidian',
    folder: '00 Inbox/Ideas'
  },

  knowledge: {
    system: 'obsidian',
    folder: '04 Knowledge'
  },

  journal: {
    system: 'obsidian',
    folder: '05 Journal'
  },

  project: {
    system: 'obsidian',
    folder: '02 Projects'
  },

  calendar_event: {
  system: 'obsidian',
  folder: '00 Inbox/Calendar'
  },

  note: {
    system: 'obsidian',
    folder: '00 Inbox'
  },

  question: {
    system: 'obsidian',
    folder: '00 Inbox'
  },

  reference: {
    system: 'obsidian',
    folder: '04 Knowledge'
  },

  unknown: {
    system: 'obsidian',
    folder: '00 Inbox'
  }
};

const route = routes[data.ai_type] || routes.unknown;

return [
  {
    json: {
      ...data,
      target_system: route.system,
      target_folder: route.folder,
      routed: true
    }
  }
];

const fs = require('fs');

const data = $input.first().json;

const source = data.source || 'telegram';
const content = String(data.content || data.ai_content || '').replace(/^=/, '').trim();

const safeTitle = String(data.ai_title || 'Untitled')
  .replace(/[\\/:*?"<>|]/g, '')
  .slice(0, 80);

const filePath = `/data/obsidian/${data.target_folder}/tg-${data.update_id}-${safeTitle}.md`;

const tagsYaml = Array.isArray(data.ai_tags)
  ? data.ai_tags.map(tag => `  - ${tag}`).join('\n')
  : '';

const entitiesYaml = Array.isArray(data.ai_entities)
  ? data.ai_entities.map(entity => `  - ${entity}`).join('\n')
  : '';

const markdown = `---
id: tg-${data.update_id}
source: ${source}
type: ${data.ai_type}
destination: ${data.ai_destination}
priority: ${data.ai_priority}
created: ${new Date(data.date * 1000).toISOString()}
confidence: ${data.ai_confidence}
status: new

tags:
${tagsYaml}

entities:
${entitiesYaml}
---

# ${data.ai_title}

## Summary

${data.ai_summary}

---

## Original Message

${content}

---

## Metadata

- User: ${data.first_name}
- Username: ${data.username}
- Chat ID: ${data.chat_id}
- Update ID: ${data.update_id}
`;


return [{
    json:{
        ...data,
        file_path:filePath,
        markdown
    }
}];

const fs = require('fs');

const data = $input.first().json;

fs.writeFileSync(
    data.file_path,
    data.markdown,
    'utf8'
);

return [{
    json: {
        ...data,
        saved_to_obsidian: true
    }
}];

