={{
({
  summary: $json.ai_title,
  description: $json.ai_summary,

  start: $json.ai_all_day
    ? {
        date: DateTime
          .fromISO($json.ai_datetime)
          .toISODate()
      }
    : {
        dateTime: DateTime
          .fromISO($json.ai_datetime, { zone: 'Asia/Novosibirsk' })
          .toISO(),
        timeZone: 'Asia/Novosibirsk'
      },

  end: $json.ai_all_day
    ? {
        date: DateTime
          .fromISO($json.ai_datetime)
          .plus({ days: 1 })
          .toISODate()
      }
    : {
        dateTime: DateTime
          .fromISO($json.ai_datetime, { zone: 'Asia/Novosibirsk' })
          .plus({ minutes: $json.ai_duration_minutes ?? 60 })
          .toISO(),
        timeZone: 'Asia/Novosibirsk'
      },

  recurrence: [
    $json.ai_recurrence
  ]
})
}}
